// Unwrap NocoDB Data API v3 response — high-fit untailored jobs
const response = $input.first().json;
const records = response.records || [];
if (records.length === 0) {
  return [{ json: { _empty: true, _message: 'No high-fit jobs needing tailoring' } }];
}
return records.map(record => ({
  json: {
    ...record.fields,
    id: record.id
  }
}));

// Unwrap NocoDB Data API v3 response — transforms { records: [...], next, prev } into flat items
const response = $input.first().json;
const records = response.records || [];

if (records.length === 0) {
  return [{ json: { _empty: true, _message: 'No Profile found' } }];
}

return records.map(record => ({
  json: {
    ...record.fields,
    id: record.id
  }
}));

// Build the CV tailoring prompt from Profile data and job details

const profileItems = $('Unwrap Profile').all();
if (!profileItems || profileItems.length === 0) {
  throw new Error('Profile table is empty. Add your profile row before running.');
}
const profile = profileItems[0].json;

const allJobs = $('Unwrap High Fit Jobs').all();
const jobs = allJobs.filter(item => !item.json._empty);

// Get CV markdown from Profile — handle both flat and nested field shapes
const cvMarkdown = profile.fields 
  ? (profile.fields['CV Markdown'] || profile.fields['Professional Summary'] || '')
  : (profile['CV Markdown'] || profile['Professional Summary'] || '');

if (!cvMarkdown) {
  throw new Error('CV Markdown is empty in Profile table. Please add your CV markdown to the Profile.');
}

const systemPrompt = `You are an expert CV writer specializing in ATS-optimized resumes for technical professionals.

RULES:
- Keep ALL factual information accurate — do NOT invent experience, companies, dates, or metrics
- Rewrite the Professional Summary (first paragraph after contact info) to mirror the JD's language and priorities
- Reorder and re-emphasize bullet points to highlight matched skills
- De-emphasize (don't remove) experience unrelated to this role
- Incorporate the tailoring notes provided
- Keep the EXACT SAME markdown structure as the original CV:
  - First line: Full name in caps
  - Second line: Contact info separated by pipes
  - Third paragraph: Professional summary
  - ALL-CAPS section headers (TECHNICAL SKILLS, etc.)
  - Skills in "Category: items" format
  - Bullet points with • character
  - Job titles with | separators for company/location/dates
  - Project names as standalone bold descriptive lines
- Output clean text. No markdown formatting (no **, no ##, no ---). No commentary, no preamble.
- The output must be a single-page CV. Do not add content that would push it beyond one page.
CRITICAL: Do NOT use <thought> tags or any thinking/reasoning before your response. Start your response directly with the tailored CV content. No preamble, no explanation.`;

return jobs.map(job => {
  const fields = job.json.fields || job.json;
  const recordId = job.json.id;
  if (!recordId) throw new Error('Missing NocoDB record id on job item');

  return {
    json: {
      _systemPrompt: systemPrompt,
      _cvMarkdown: cvMarkdown,
      _jobDescription: fields['Job Description'] || '',
      _matchedSkills: fields['Matched Skills'] || '',
      _cvTailoringNotes: fields['CV Tailoring Notes'] || '',
      _jobTitle: fields['Job Title'] || '',
      _company: fields['Company'] || '',
      _recordId: recordId
    }
  };
});

