// Parse the tailored CV from AI response and prepare for rendering + Airtable update
const aiResponse = $input.first().json;

// Extract content — handle both simplified and full response shapes
let tailoredCV;
if (aiResponse.choices && aiResponse.choices[0] && aiResponse.choices[0].message) {
  tailoredCV = aiResponse.choices[0].message.content;
} else if (aiResponse.message && aiResponse.message.content) {
  tailoredCV = aiResponse.message.content;
} else if (aiResponse.content) {
  tailoredCV = aiResponse.content;
} else if (aiResponse.text) {
  tailoredCV = aiResponse.text;
} else {
  tailoredCV = typeof aiResponse === 'string' ? aiResponse : JSON.stringify(aiResponse);
}

// Strip <thought> tags and everything inside them
if (typeof tailoredCV === 'string' && tailoredCV.includes('<thought>')) {
  const thoughtEnd = tailoredCV.indexOf('</thought>');
  if (thoughtEnd !== -1) {
    tailoredCV = tailoredCV.substring(thoughtEnd + '</thought>'.length).trim();
  } else {
    // No closing tag — find first line that looks like CV content
    const lines = tailoredCV.split('\n');
    const cvStart = lines.findIndex(l => l.trim().length > 0 && !l.trim().startsWith('<thought>') && !l.includes('*   '));
    if (cvStart !== -1) {
      tailoredCV = lines.slice(cvStart).join('\n').trim();
    }
  }
}

if (!tailoredCV || tailoredCV.length < 100) {
  throw new Error('Tailored CV response too short or empty: ' + (tailoredCV || '').slice(0, 200));
}

// Calculate cost from actual token usage
const INPUT_COST_PER_TOKEN = 0.25 / 1_000_000;
const OUTPUT_COST_PER_TOKEN = 2.00 / 1_000_000;
let cost = 0;
const usage = aiResponse.usage 
  || (aiResponse.message && aiResponse.message.usage)
  || null;
if (usage && usage.prompt_tokens && usage.completion_tokens) {
  cost = (usage.prompt_tokens * INPUT_COST_PER_TOKEN) 
    + (usage.completion_tokens * OUTPUT_COST_PER_TOKEN);
  cost = Math.round(cost * 1_000_000) / 1_000_000;
}

// Get job context from the loop
const loopItem = $('Loop Over Jobs').item.json;
const safeCompany = loopItem._company.replace(/[^a-zA-Z0-9]/g, '_').toLowerCase();
const filename = `cv_${safeCompany}_${Date.now()}`;

return [{
  json: {
    recordId: loopItem._recordId,
    tailoredCV: tailoredCV,
    company: loopItem._company,
    jobTitle: loopItem._jobTitle,
    cost: cost,
    filename: filename
  }
}];
